/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_NextInputs */

const en_site_next = /** @type {(inputs: Site_NextInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Next`)
};

const zh_cn2_site_next = /** @type {(inputs: Site_NextInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`下一页`)
};

const ja_site_next = /** @type {(inputs: Site_NextInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`次`)
};

/**
* | output |
* | --- |
* | "Next" |
*
* @param {Site_NextInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_next = /** @type {((inputs?: Site_NextInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_NextInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_next(inputs)
	if (locale === "ja") return ja_site_next(inputs)
	return en_site_next(inputs)
});