/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_ScreenshotInputs */

const en_site_screenshot = /** @type {(inputs: Site_ScreenshotInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`screenshot`)
};

const zh_cn2_site_screenshot = /** @type {(inputs: Site_ScreenshotInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`截图`)
};

const ja_site_screenshot = /** @type {(inputs: Site_ScreenshotInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`スクリーンショット`)
};

/**
* | output |
* | --- |
* | "screenshot" |
*
* @param {Site_ScreenshotInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_screenshot = /** @type {((inputs?: Site_ScreenshotInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_ScreenshotInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_screenshot(inputs)
	if (locale === "ja") return ja_site_screenshot(inputs)
	return en_site_screenshot(inputs)
});