/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_CheckingInputs */

const en_site_checking = /** @type {(inputs: Site_CheckingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Checking…`)
};

const zh_cn2_site_checking = /** @type {(inputs: Site_CheckingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Checking…`)
};

const ja_site_checking = /** @type {(inputs: Site_CheckingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`チェック中…`)
};

/**
* | output |
* | --- |
* | "Checking…" |
*
* @param {Site_CheckingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_checking = /** @type {((inputs?: Site_CheckingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_CheckingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_checking(inputs)
	if (locale === "ja") return ja_site_checking(inputs)
	return en_site_checking(inputs)
});