/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_CopiedInputs */

const en_site_copied = /** @type {(inputs: Site_CopiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Copied`)
};

const zh_cn2_site_copied = /** @type {(inputs: Site_CopiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已复制`)
};

const ja_site_copied = /** @type {(inputs: Site_CopiedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`コピーされました`)
};

/**
* | output |
* | --- |
* | "Copied" |
*
* @param {Site_CopiedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_copied = /** @type {((inputs?: Site_CopiedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_CopiedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_copied(inputs)
	if (locale === "ja") return ja_site_copied(inputs)
	return en_site_copied(inputs)
});