/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_UpdatedInputs */

const en_site_updated = /** @type {(inputs: Site_UpdatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Updated`)
};

const zh_cn2_site_updated = /** @type {(inputs: Site_UpdatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已更新`)
};

const ja_site_updated = /** @type {(inputs: Site_UpdatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`更新されました`)
};

/**
* | output |
* | --- |
* | "Updated" |
*
* @param {Site_UpdatedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_updated = /** @type {((inputs?: Site_UpdatedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_UpdatedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_updated(inputs)
	if (locale === "ja") return ja_site_updated(inputs)
	return en_site_updated(inputs)
});