/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_SearchmodeInputs */

const en_site_searchmode = /** @type {(inputs: Site_SearchmodeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search mode`)
};

const zh_cn2_site_searchmode = /** @type {(inputs: Site_SearchmodeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search mode`)
};

const ja_site_searchmode = /** @type {(inputs: Site_SearchmodeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`検索モード`)
};

/**
* | output |
* | --- |
* | "Search mode" |
*
* @param {Site_SearchmodeInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_searchmode = /** @type {((inputs?: Site_SearchmodeInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_SearchmodeInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_searchmode(inputs)
	if (locale === "ja") return ja_site_searchmode(inputs)
	return en_site_searchmode(inputs)
});