/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_SearchingInputs */

const en_site_searching = /** @type {(inputs: Site_SearchingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Searching…`)
};

const zh_cn2_site_searching = /** @type {(inputs: Site_SearchingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Searching…`)
};

const ja_site_searching = /** @type {(inputs: Site_SearchingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`検索中…`)
};

/**
* | output |
* | --- |
* | "Searching…" |
*
* @param {Site_SearchingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_searching = /** @type {((inputs?: Site_SearchingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_SearchingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_searching(inputs)
	if (locale === "ja") return ja_site_searching(inputs)
	return en_site_searching(inputs)
});