/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_PageunavailableInputs */

const en_site_pageunavailable = /** @type {(inputs: Site_PageunavailableInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`This page is not available.`)
};

const zh_cn2_site_pageunavailable = /** @type {(inputs: Site_PageunavailableInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`该页面不可用。`)
};

const ja_site_pageunavailable = /** @type {(inputs: Site_PageunavailableInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このページは利用できません。`)
};

/**
* | output |
* | --- |
* | "This page is not available." |
*
* @param {Site_PageunavailableInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_pageunavailable = /** @type {((inputs?: Site_PageunavailableInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_PageunavailableInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_pageunavailable(inputs)
	if (locale === "ja") return ja_site_pageunavailable(inputs)
	return en_site_pageunavailable(inputs)
});