/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_ChangelanguageInputs */

const en_site_changelanguage = /** @type {(inputs: Site_ChangelanguageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Change language`)
};

const zh_cn2_site_changelanguage = /** @type {(inputs: Site_ChangelanguageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`更改语言`)
};

const ja_site_changelanguage = /** @type {(inputs: Site_ChangelanguageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`言語を変更する`)
};

/**
* | output |
* | --- |
* | "Change language" |
*
* @param {Site_ChangelanguageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_changelanguage = /** @type {((inputs?: Site_ChangelanguageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_ChangelanguageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_changelanguage(inputs)
	if (locale === "ja") return ja_site_changelanguage(inputs)
	return en_site_changelanguage(inputs)
});