import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_SynthesizingInputs */

const en_site_synthesizing = /** @type {(inputs: Site_SynthesizingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Synthesizing answer from verified documentation…`)
};

const zh_cn2_site_synthesizing = /** @type {(inputs: Site_SynthesizingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`正在根据官方文档生成回答…`)
};

const ja_site_synthesizing = /** @type {(inputs: Site_SynthesizingInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`検証されたドキュメントから回答を合成中…`)
};

/**
* | output |
* | --- |
* | "Synthesizing answer from verified documentation…" |
*
* @param {Site_SynthesizingInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_synthesizing = /** @type {((inputs?: Site_SynthesizingInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_SynthesizingInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_synthesizing(inputs)
	if (locale === "ja") return ja_site_synthesizing(inputs)
	return en_site_synthesizing(inputs)
});