import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_RaiseissueInputs */

const en_site_raiseissue = /** @type {(inputs: Site_RaiseissueInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Raise an issue`)
};

