import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_ReadytoanswerInputs */

const en_site_readytoanswer = /** @type {(inputs: Site_ReadytoanswerInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Ready to answer`)
};

const zh_cn2_site_readytoanswer = /** @type {(inputs: Site_ReadytoanswerInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`准备就绪`)
};

const ja_site_readytoanswer = /** @type {(inputs: Site_ReadytoanswerInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`質問の準備ができました`)
};

/**
* | output |
* | --- |
* | "Ready to answer" |
*
* @param {Site_ReadytoanswerInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_readytoanswer = /** @type {((inputs?: Site_ReadytoanswerInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_ReadytoanswerInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_readytoanswer(inputs)
	if (locale === "ja") return ja_site_readytoanswer(inputs)
	return en_site_readytoanswer(inputs)
});