/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_DeprecatedInputs */

const en_site_deprecated = /** @type {(inputs: Site_DeprecatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`deprecated`)
};

const zh_cn2_site_deprecated = /** @type {(inputs: Site_DeprecatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`已弃用`)
};

const ja_site_deprecated = /** @type {(inputs: Site_DeprecatedInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`廃止された`)
};

/**
* | output |
* | --- |
* | "deprecated" |
*
* @param {Site_DeprecatedInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_deprecated = /** @type {((inputs?: Site_DeprecatedInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_DeprecatedInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_deprecated(inputs)
	if (locale === "ja") return ja_site_deprecated(inputs)
	return en_site_deprecated(inputs)
});