/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_EditpageInputs */

const en_site_editpage = /** @type {(inputs: Site_EditpageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Edit this page`)
};

const zh_cn2_site_editpage = /** @type {(inputs: Site_EditpageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`编辑本页`)
};

const ja_site_editpage = /** @type {(inputs: Site_EditpageInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このページを編集する`)
};

/**
* | output |
* | --- |
* | "Edit this page" |
*
* @param {Site_EditpageInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_editpage = /** @type {((inputs?: Site_EditpageInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_EditpageInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_editpage(inputs)
	if (locale === "ja") return ja_site_editpage(inputs)
	return en_site_editpage(inputs)
});