import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_PreviousInputs */

const en_site_previous = /** @type {(inputs: Site_PreviousInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Previous`)
};

const zh_cn2_site_previous = /** @type {(inputs: Site_PreviousInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`上一页`)
};

const ja_site_previous = /** @type {(inputs: Site_PreviousInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`前の`)
};

/**
* | output |
* | --- |
* | "Previous" |
*
* @param {Site_PreviousInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_previous = /** @type {((inputs?: Site_PreviousInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_PreviousInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_previous(inputs)
	if (locale === "ja") return ja_site_previous(inputs)
	return en_site_previous(inputs)
});