import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_ResultsInputs */

const en_site_results = /** @type {(inputs: Site_ResultsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Results`)
};

const zh_cn2_site_results = /** @type {(inputs: Site_ResultsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`结果`)
};

const ja_site_results = /** @type {(inputs: Site_ResultsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`結果`)
};

/**
* | output |
* | --- |
* | "Results" |
*
* @param {Site_ResultsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_results = /** @type {((inputs?: Site_ResultsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_ResultsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_results(inputs)
	if (locale === "ja") return ja_site_results(inputs)
	return en_site_results(inputs)
});