/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_SearchInputs */

const en_site_search = /** @type {(inputs: Site_SearchInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search…`)
};

const zh_cn2_site_search = /** @type {(inputs: Site_SearchInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`搜索...`)
};

const ja_site_search = /** @type {(inputs: Site_SearchInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`検索…`)
};

/**
* | output |
* | --- |
* | "Search…" |
*
* @param {Site_SearchInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_search = /** @type {((inputs?: Site_SearchInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_SearchInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_search(inputs)
	if (locale === "ja") return ja_site_search(inputs)
	return en_site_search(inputs)
});