/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_SearchpromptInputs */

const en_site_searchprompt = /** @type {(inputs: Site_SearchpromptInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Type to search…`)
};

const zh_cn2_site_searchprompt = /** @type {(inputs: Site_SearchpromptInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`输入搜索...`)
};

const ja_site_searchprompt = /** @type {(inputs: Site_SearchpromptInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`検索するには入力してください…`)
};

/**
* | output |
* | --- |
* | "Type to search…" |
*
* @param {Site_SearchpromptInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_searchprompt = /** @type {((inputs?: Site_SearchpromptInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_SearchpromptInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_searchprompt(inputs)
	if (locale === "ja") return ja_site_searchprompt(inputs)
	return en_site_searchprompt(inputs)
});