/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_SearchplaceholderInputs */

const en_site_searchplaceholder = /** @type {(inputs: Site_SearchplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search documentation…`)
};

const zh_cn2_site_searchplaceholder = /** @type {(inputs: Site_SearchplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`搜索文档...`)
};

const ja_site_searchplaceholder = /** @type {(inputs: Site_SearchplaceholderInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドキュメントを検索…`)
};

/**
* | output |
* | --- |
* | "Search documentation…" |
*
* @param {Site_SearchplaceholderInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_searchplaceholder = /** @type {((inputs?: Site_SearchplaceholderInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_SearchplaceholderInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_searchplaceholder(inputs)
	if (locale === "ja") return ja_site_searchplaceholder(inputs)
	return en_site_searchplaceholder(inputs)
});