/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_SearchdocumentationInputs */

const en_site_searchdocumentation = /** @type {(inputs: Site_SearchdocumentationInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Search documentation`)
};

const zh_cn2_site_searchdocumentation = /** @type {(inputs: Site_SearchdocumentationInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`搜索文档`)
};

const ja_site_searchdocumentation = /** @type {(inputs: Site_SearchdocumentationInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドキュメントの検索`)
};

/**
* | output |
* | --- |
* | "Search documentation" |
*
* @param {Site_SearchdocumentationInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_searchdocumentation = /** @type {((inputs?: Site_SearchdocumentationInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_SearchdocumentationInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_searchdocumentation(inputs)
	if (locale === "ja") return ja_site_searchdocumentation(inputs)
	return en_site_searchdocumentation(inputs)
});