/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_RequiredInputs */

const en_site_required = /** @type {(inputs: Site_RequiredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`required`)
};

const zh_cn2_site_required = /** @type {(inputs: Site_RequiredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`必填`)
};

const ja_site_required = /** @type {(inputs: Site_RequiredInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`必須`)
};

/**
* | output |
* | --- |
* | "required" |
*
* @param {Site_RequiredInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_required = /** @type {((inputs?: Site_RequiredInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_RequiredInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_required(inputs)
	if (locale === "ja") return ja_site_required(inputs)
	return en_site_required(inputs)
});