import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_ConnectionerrorInputs */

const en_site_connectionerror = /** @type {(inputs: Site_ConnectionerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Verify your connection or try rephrasing.`)
};

const zh_cn2_site_connectionerror = /** @type {(inputs: Site_ConnectionerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`请检查网络连接或尝试换个说法。`)
};

const ja_site_connectionerror = /** @type {(inputs: Site_ConnectionerrorInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`接続を確認するか、言い回しを変更してお試しください。`)
};

/**
* | output |
* | --- |
* | "Verify your connection or try rephrasing." |
*
* @param {Site_ConnectionerrorInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_connectionerror = /** @type {((inputs?: Site_ConnectionerrorInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_ConnectionerrorInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_connectionerror(inputs)
	if (locale === "ja") return ja_site_connectionerror(inputs)
	return en_site_connectionerror(inputs)
});