import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_DismissbannerInputs */

const en_site_dismissbanner = /** @type {(inputs: Site_DismissbannerInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Dismiss banner`)
};

const zh_cn2_site_dismissbanner = /** @type {(inputs: Site_DismissbannerInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`关闭横幅`)
};

const ja_site_dismissbanner = /** @type {(inputs: Site_DismissbannerInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`バナーを閉じる`)
};

/**
* | output |
* | --- |
* | "Dismiss banner" |
*
* @param {Site_DismissbannerInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_dismissbanner = /** @type {((inputs?: Site_DismissbannerInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_DismissbannerInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_dismissbanner(inputs)
	if (locale === "ja") return ja_site_dismissbanner(inputs)
	return en_site_dismissbanner(inputs)
});