/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_NotpublishedtitleInputs */

const en_site_notpublishedtitle = /** @type {(inputs: Site_NotpublishedtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Not published yet`)
};

const zh_cn2_site_notpublishedtitle = /** @type {(inputs: Site_NotpublishedtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`尚未发布`)
};

const ja_site_notpublishedtitle = /** @type {(inputs: Site_NotpublishedtitleInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`まだ公開されていません`)
};

/**
* | output |
* | --- |
* | "Not published yet" |
*
* @param {Site_NotpublishedtitleInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_notpublishedtitle = /** @type {((inputs?: Site_NotpublishedtitleInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_NotpublishedtitleInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_notpublishedtitle(inputs)
	if (locale === "ja") return ja_site_notpublishedtitle(inputs)
	return en_site_notpublishedtitle(inputs)
});