import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_SourcesInputs */

const en_site_sources = /** @type {(inputs: Site_SourcesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Sources`)
};

const zh_cn2_site_sources = /** @type {(inputs: Site_SourcesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Sources`)
};

const ja_site_sources = /** @type {(inputs: Site_SourcesInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`情報源`)
};

/**
* | output |
* | --- |
* | "Sources" |
*
* @param {Site_SourcesInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_sources = /** @type {((inputs?: Site_SourcesInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_SourcesInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_sources(inputs)
	if (locale === "ja") return ja_site_sources(inputs)
	return en_site_sources(inputs)
});