/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_ScreenshotsInputs */

const en_site_screenshots = /** @type {(inputs: Site_ScreenshotsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`screenshots`)
};

const zh_cn2_site_screenshots = /** @type {(inputs: Site_ScreenshotsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`截图`)
};

const ja_site_screenshots = /** @type {(inputs: Site_ScreenshotsInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`スクリーンショット`)
};

/**
* | output |
* | --- |
* | "screenshots" |
*
* @param {Site_ScreenshotsInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_screenshots = /** @type {((inputs?: Site_ScreenshotsInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_ScreenshotsInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_screenshots(inputs)
	if (locale === "ja") return ja_site_screenshots(inputs)
	return en_site_screenshots(inputs)
});