/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_SearchdescriptionInputs */

const en_site_searchdescription = /** @type {(inputs: Site_SearchdescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Full-text and fuzzy search across this site.`)
};

const zh_cn2_site_searchdescription = /** @type {(inputs: Site_SearchdescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`本网站的全文搜索和模糊搜索。`)
};

const ja_site_searchdescription = /** @type {(inputs: Site_SearchdescriptionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`このサイト全体の全文およびあいまい検索。`)
};

/**
* | output |
* | --- |
* | "Full-text and fuzzy search across this site." |
*
* @param {Site_SearchdescriptionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_searchdescription = /** @type {((inputs?: Site_SearchdescriptionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_SearchdescriptionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_searchdescription(inputs)
	if (locale === "ja") return ja_site_searchdescription(inputs)
	return en_site_searchdescription(inputs)
});