import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_CopycodeInputs */

const en_site_copycode = /** @type {(inputs: Site_CopycodeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Copy code`)
};

const zh_cn2_site_copycode = /** @type {(inputs: Site_CopycodeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`复制代码`)
};

const ja_site_copycode = /** @type {(inputs: Site_CopycodeInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`コードをコピーする`)
};

/**
* | output |
* | --- |
* | "Copy code" |
*
* @param {Site_CopycodeInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_copycode = /** @type {((inputs?: Site_CopycodeInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_CopycodeInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_copycode(inputs)
	if (locale === "ja") return ja_site_copycode(inputs)
	return en_site_copycode(inputs)
});