import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_ChangeversionInputs */

const en_site_changeversion = /** @type {(inputs: Site_ChangeversionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Change docs version`)
};

const zh_cn2_site_changeversion = /** @type {(inputs: Site_ChangeversionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`更改文档版本`)
};

const ja_site_changeversion = /** @type {(inputs: Site_ChangeversionInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`ドキュメントのバージョンを変更する`)
};

/**
* | output |
* | --- |
* | "Change docs version" |
*
* @param {Site_ChangeversionInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_changeversion = /** @type {((inputs?: Site_ChangeversionInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_ChangeversionInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_changeversion(inputs)
	if (locale === "ja") return ja_site_changeversion(inputs)
	return en_site_changeversion(inputs)
});