/* eslint-disable */
import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_ReadytoanswerhintInputs */

const en_site_readytoanswerhint = /** @type {(inputs: Site_ReadytoanswerhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Type your question above and press ↵ or click Ask AI`)
};

const zh_cn2_site_readytoanswerhint = /** @type {(inputs: Site_ReadytoanswerhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`在上方输入您的问题并按 ↵ 或点击“问答 AI”`)
};

const ja_site_readytoanswerhint = /** @type {(inputs: Site_ReadytoanswerhintInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`上に質問を入力して ↵ を押すか、「AIに質問」をクリックしてください`)
};

/**
* | output |
* | --- |
* | "Type your question above and press ↵ or click Ask AI" |
*
* @param {Site_ReadytoanswerhintInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_readytoanswerhint = /** @type {((inputs?: Site_ReadytoanswerhintInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_ReadytoanswerhintInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_readytoanswerhint(inputs)
	if (locale === "ja") return ja_site_readytoanswerhint(inputs)
	return en_site_readytoanswerhint(inputs)
});