import { getLocale, experimentalStaticLocale } from '../runtime.js';

/** @typedef {import('../runtime.js').LocalizedString} LocalizedString */

/** @typedef {{}} Site_BacktosearchInputs */

const en_site_backtosearch = /** @type {(inputs: Site_BacktosearchInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`Back to search`)
};

const zh_cn2_site_backtosearch = /** @type {(inputs: Site_BacktosearchInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`返回搜索`)
};

const ja_site_backtosearch = /** @type {(inputs: Site_BacktosearchInputs) => LocalizedString} */ () => {
	return /** @type {LocalizedString} */ (`検索に戻る`)
};

/**
* | output |
* | --- |
* | "Back to search" |
*
* @param {Site_BacktosearchInputs} inputs
* @param {{ locale?: "en" | "zh-CN" | "ja" }} options
* @returns {LocalizedString}
*/
export const site_backtosearch = /** @type {((inputs?: Site_BacktosearchInputs, options?: { locale?: "en" | "zh-CN" | "ja" }) => LocalizedString) & import('../runtime.js').MessageMetadata<Site_BacktosearchInputs, { locale?: "en" | "zh-CN" | "ja" }, {}>} */ ((inputs = {}, options = {}) => {
	const locale = experimentalStaticLocale ?? options.locale ?? getLocale()
	if (locale === "zh-CN") return zh_cn2_site_backtosearch(inputs)
	if (locale === "ja") return ja_site_backtosearch(inputs)
	return en_site_backtosearch(inputs)
});